import { Injectable } from '@nestjs/common';
import Redis from 'ioredis';

const GEO_KEY = 'drivers:geo';
const REDIS_HOST = process.env.REDIS_HOST ?? 'localhost';
const REDIS_PORT = Number(process.env.REDIS_PORT ?? 6379);

/**
 * Tracks live driver GPS coordinates in a single Redis GEO sorted set
 * and answers "who is nearby" for the rider-matching flow.
 */
@Injectable()
export class DriverLocationService {
  /**
   * Called by the driver app several times per second while a shift is active.
   */
  async updateDriverLocation(
    driverId: string,
    lng: number,
    lat: number,
  ): Promise<void> {
    const redis = new Redis({ host: REDIS_HOST, port: REDIS_PORT });

    await redis.geoadd(GEO_KEY, lng, lat, driverId);

    await redis.quit();
  }

  /**
   * Called by the rider app to list available drivers within radiusKm.
   */
  async findNearbyDrivers(
    lng: number,
    lat: number,
    radiusKm: number,
  ): Promise<string[]> {
    const redis = new Redis({ host: REDIS_HOST, port: REDIS_PORT });

    const driverIds = (await redis.geosearch(
      GEO_KEY,
      'FROMLONLAT',
      lng,
      lat,
      'BYRADIUS',
      radiusKm,
      'km',
      'ASC',
    )) as string[];

    await redis.quit();

    return driverIds;
  }
}

